import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import humanTime from 'flarum/common/helpers/humanTime';
import blockEvidence from '../utils/blockEvidence';
const PREFIX = 'fof-anti-spam.admin.blocked_registrations.evidence';

/**
 * What StopForumSpam reported, per field, at a glance.
 *
 * This shows evidence rather than declaring a single cause. Most blocks trip several rules at
 * once, and a row blocked under one set of thresholds may match none of the current ones, so
 * naming "the" reason would often be wrong. Where the rules that fired were recorded at block
 * time we state them as fact; otherwise we present the signals and let the admin judge.
 */
export default class BlockEvidenceSummary extends Component {
  view() {
    const evidence = blockEvidence(this.attrs.registration);
    if (evidence.lookupFailed) {
      return m("div", {
        className: "BlockEvidence BlockEvidence--empty"
      }, app.translator.trans("".concat(PREFIX, ".lookup_failed")));
    }
    if (!evidence.fields.length) {
      return m("div", {
        className: "BlockEvidence BlockEvidence--empty"
      }, app.translator.trans("".concat(PREFIX, ".none")));
    }
    return m("div", {
      className: "BlockEvidence"
    }, this.recordedReasons(evidence.reasons), m("ul", {
      className: "BlockEvidence-fields"
    }, evidence.fields.map(field => this.field(field))));
  }

  /**
   * The rules that actually fired. Absent on older rows, where we say nothing rather than
   * guessing from thresholds that may since have changed.
   */
  recordedReasons(reasons) {
    if (!(reasons != null && reasons.length)) return null;
    return m("div", {
      className: "BlockEvidence-reasons"
    }, m("span", {
      className: "BlockEvidence-reasonsLabel"
    }, app.translator.trans("".concat(PREFIX, ".blocked_by"))), reasons.map(reason => m("span", {
      className: "BlockEvidence-reason"
    }, app.translator.trans("".concat(PREFIX, ".rule.").concat(reason)))));
  }
  field(field) {
    const badges = this.badges(field);
    return m("li", {
      className: "BlockEvidence-field BlockEvidence-field--".concat(field.field)
    }, m("span", {
      className: "BlockEvidence-fieldName"
    }, app.translator.trans("".concat(PREFIX, ".field.").concat(field.field))), m("span", {
      className: "BlockEvidence-badges"
    }, badges));
  }
  badges(field) {
    const badges = [];
    if (field.blacklisted) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--critical"
      }, app.translator.trans("".concat(PREFIX, ".badge.blacklisted"))));
    }
    if (field.torexit) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--critical"
      }, app.translator.trans("".concat(PREFIX, ".badge.tor_exit"))));
    }

    // A field nobody has ever reported is worth stating plainly: it tells the admin which part
    // of the registration was clean, which is as useful as knowing which part was not.
    if (!field.appears && !field.blacklisted) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--clean"
      }, app.translator.trans("".concat(PREFIX, ".badge.not_listed"))));
      return badges;
    }
    if (field.confidence !== null) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--".concat(field.confidence >= 50 ? 'warning' : 'muted')
      }, app.translator.trans("".concat(PREFIX, ".badge.confidence"), {
        value: field.confidence.toFixed(2)
      })));
    }
    if (field.frequency) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--muted"
      }, app.translator.trans("".concat(PREFIX, ".badge.frequency"), {
        count: field.frequency
      })));
    }
    if (field.lastseen) {
      const seen = new Date(field.lastseen);
      if (!isNaN(seen.getTime())) {
        badges.push(m("span", {
          className: "BlockEvidence-badge BlockEvidence-badge--muted"
        }, app.translator.trans("".concat(PREFIX, ".badge.last_seen"), {
          when: humanTime(seen)
        })));
      }
    }

    // Only meaningful on the IP, and only worth the space when SFS actually returned one.
    if (field.asn) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--muted"
      }, app.translator.trans("".concat(PREFIX, ".badge.asn"), {
        asn: field.asn
      })));
    }

    // The address the spammer actually controls, once plus-addressing and dot-tricks are undone.
    if (field.normalized && field.normalized !== field.value) {
      badges.push(m("span", {
        className: "BlockEvidence-badge BlockEvidence-badge--muted"
      }, app.translator.trans("".concat(PREFIX, ".badge.normalized"), {
        value: field.normalized
      })));
    }
    return badges;
  }
}
flarum.reg.add('fof-anti-spam', 'admin/components/BlockEvidenceSummary', BlockEvidenceSummary);